// SetLogic replaces the registered business logic for this record only (tests); no
// arguments runs no triggers at all.
func (t *Vendor) SetLogic(logic ...any) {
	for _, l := range logic {
		checkLogic(VendorTableName, "Vendor", l, vendorTrigger)
	}
	if logic == nil {
		logic = []any{}
	}
	t.logic = logic
}

func (t *Vendor) registeredLogic() []any {
	if t.logic != nil {
		return t.logic
	}
	return vendorLogic
}

// runOnInsert runs the OnInsert triggers, then the field checks of the definition
func (t *Vendor) runOnInsert() error {
	for _, l := range t.registeredLogic() {
		if trg, ok := l.(VendorOnInsert); ok {
			if err := trg.OnInsert(t); err != nil {
				return err
			}
		}
	}
	return t.CheckFields()
}

