// CreateTable creates the Vendor table for the specified company (SQLite)
// The db parameter can be either *sql.DB or *sql.Tx
func (t *Vendor) CreateTable(db database.Executor, company string) error {
	return t.CreateTableWithDBType(db, company, database.DBTypeSQLite)
}

// CreateTableWithDBType creates the Vendor table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *Vendor) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, VendorTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetVendorPostgresTableSchema()
	} else {
		schema = GetVendorTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Vendor table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *Vendor) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, VendorTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (no)`,
		fmt.Sprintf("%s$Vendor$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (search_name)`,
		fmt.Sprintf("%s$Vendor$search_name", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index search_name: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (vendor_posting_group)`,
		fmt.Sprintf("%s$Vendor$vendor_posting_group", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index vendor_posting_group: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (priority)`,
		fmt.Sprintf("%s$Vendor$priority", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index priority: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (currency_code)`,
		fmt.Sprintf("%s$Vendor$currency_code", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index currency_code: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (country_code)`,
		fmt.Sprintf("%s$Vendor$country_code", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index country_code: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (gen_bus_posting_group)`,
		fmt.Sprintf("%s$Vendor$gen_bus_posting_group", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index gen_bus_posting_group: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (purchaser_code)`,
		fmt.Sprintf("%s$Vendor$purchaser_code", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index purchaser_code: %w", err)
	}
	var keys []sift.Key
	for _, spec := range vendorSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, VendorTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, VendorTableName, keys)
}

// vendorSIFTSpecs are the table's keys with sum_index_fields
func vendorSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *Vendor) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, VendorTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range vendorSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, VendorTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: VendorTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, VendorTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

