// Insert inserts the record into the database
func (t *Vendor) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, VendorTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.No,
		t.Name,
		t.Search_name,
		t.Name_2,
		t.Address,
		t.Address_2,
		t.City,
		t.Contact,
		t.Phone_no,
		t.Telex_no,
		t.Our_account_no,
		t.Territory_code,
		t.Department_code,
		t.Project_code,
		t.Budgeted_amount,
		t.Vendor_posting_group,
		t.Currency_code,
		t.Language_code,
		t.Statistics_group,
		t.Payment_terms_code,
		t.Fin_charge_terms_code,
		t.Purchaser_code,
		t.Shipment_method_code,
		t.Shipping_agent_code,
		t.Invoice_disc_code,
		t.Country_code,
		t.Blocked,
		t.Pay_to_vendor_no,
		t.Priority,
		t.Payment_method_code,
		t.Last_date_modified,
		t.Application_method,
		t.Fax_no,
		t.Telex_answer_back,
		t.Vat_registration_no,
		t.Gen_bus_posting_group,
		t.Picture,
		t.Post_code,
		t.State,
		t.E_mail,
		t.Home_page,
		t.No_series,
		t.Tax_area_code,
		t.Tax_liable,
		t.Tax_bus_posting_group,
		t.Reserve,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (no, name, search_name, name_2, address, address_2, city, contact, phone_no, telex_no, our_account_no, territory_code, department_code, project_code, budgeted_amount, vendor_posting_group, currency_code, language_code, statistics_group, payment_terms_code, fin_charge_terms_code, purchaser_code, shipment_method_code, shipping_agent_code, invoice_disc_code, country_code, blocked, pay_to_vendor_no, priority, payment_method_code, last_date_modified, application_method, fax_no, telex_answer_back, vat_registration_no, gen_bus_posting_group, picture, post_code, state, e_mail, home_page, no_series, tax_area_code, tax_liable, tax_bus_posting_group, reserve) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (no) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Vendor: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(VendorTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *Vendor) InsertAll(records []*Vendor, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.No,
			r.Name,
			r.Search_name,
			r.Name_2,
			r.Address,
			r.Address_2,
			r.City,
			r.Contact,
			r.Phone_no,
			r.Telex_no,
			r.Our_account_no,
			r.Territory_code,
			r.Department_code,
			r.Project_code,
			r.Budgeted_amount,
			r.Vendor_posting_group,
			r.Currency_code,
			r.Language_code,
			r.Statistics_group,
			r.Payment_terms_code,
			r.Fin_charge_terms_code,
			r.Purchaser_code,
			r.Shipment_method_code,
			r.Shipping_agent_code,
			r.Invoice_disc_code,
			r.Country_code,
			r.Blocked,
			r.Pay_to_vendor_no,
			r.Priority,
			r.Payment_method_code,
			r.Last_date_modified,
			r.Application_method,
			r.Fax_no,
			r.Telex_answer_back,
			r.Vat_registration_no,
			r.Gen_bus_posting_group,
			r.Picture,
			r.Post_code,
			r.State,
			r.E_mail,
			r.Home_page,
			r.No_series,
			r.Tax_area_code,
			r.Tax_liable,
			r.Tax_bus_posting_group,
			r.Reserve,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, VendorTableName)
	columns := []string{"no", "name", "search_name", "name_2", "address", "address_2", "city", "contact", "phone_no", "telex_no", "our_account_no", "territory_code", "department_code", "project_code", "budgeted_amount", "vendor_posting_group", "currency_code", "language_code", "statistics_group", "payment_terms_code", "fin_charge_terms_code", "purchaser_code", "shipment_method_code", "shipping_agent_code", "invoice_disc_code", "country_code", "blocked", "pay_to_vendor_no", "priority", "payment_method_code", "last_date_modified", "application_method", "fax_no", "telex_answer_back", "vat_registration_no", "gen_bus_posting_group", "picture", "post_code", "state", "e_mail", "home_page", "no_series", "tax_area_code", "tax_liable", "tax_bus_posting_group", "reserve"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

