// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *Vendor) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *Vendor) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"no": {{"Bank_Account_Ledger_Entry", false, "bal_account_no", "bal_account_type", 2}, {"Check_Ledger_Entry", false, "bal_account_no", "bal_account_type", 2}, {"Comment_Line", false, "no", "table_name", 2}, {"Customer Ledger Entry", false, "bal_account_no", "bal_account_type", 2}, {"FA_Ledger_Entry", false, "bal_account_no", "bal_account_type", 2}, {"Fixed_Asset", false, "vendor_no", "", 0}, {"Fixed_Asset", false, "maintenance_vendor_no", "", 0}, {"Gen_Journal_Batch", false, "bal_account_no", "bal_account_type", 2}, {"Gen_Journal_Line", false, "account_no", "account_type", 2}, {"Gen_Journal_Line", false, "bal_account_no", "bal_account_type", 2}, {"Gen_Journal_Line", false, "source_no", "source_type", 2}, {"Gen_Journal_Template", false, "bal_account_no", "bal_account_type", 2}, {"G_L_Entry", false, "bal_account_no", "bal_account_type", 2}, {"G_L_Entry", false, "source_no", "source_type", 2}, {"Insurance", false, "insurance_vendor_no", "", 0}, {"Maintenance_Registration", false, "maintenance_vendor_no", "", 0}, {"Maintenance_Ledger_Entry", false, "bal_account_no", "bal_account_type", 2}, {"Order_Address", false, "vendor_no", "", 0}, {"Vendor", false, "invoice_disc_code", "", 0}, {"Vendor", false, "pay_to_vendor_no", "", 0}, {"Vendor_Bank_Account", false, "vendor_no", "", 0}, {"Vendor Ledger Entry", false, "vendor_no", "", 0}, {"Vendor Ledger Entry", false, "buy_from_vendor_no", "", 0}, {"Vendor Ledger Entry", false, "bal_account_no", "bal_account_type", 2}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

// Delete removes the record from the database
func (t *Vendor) Delete(runTrigger bool) bool {
	// OnDelete trigger of the business logic
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnDelete(); err != nil {
			fmt.Printf("Error: OnDelete trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, VendorTableName)

	// Collect arguments for DELETE
	args := []interface{}{
		t.No,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`DELETE FROM "%s" WHERE 1=1 AND no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	_, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to delete Vendor: %v\n", err)
		return false
	}
	return true
}

